#[derive(Queryable)]
struct Party { id: i64, name: String, kind: String }

// no ORM-level inheritance: the join is written out per variant
let person: (Party, NaiveDate) = diesel::sql_query(
    "SELECT p.id, p.name, p.kind, e.birth_date \
       FROM party p JOIN person e ON e.id = p.id WHERE p.id = $1")
    .bind::<BigInt, _>(id)
    .get_result(&mut conn)?;
